import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<any>} [textContent]
 * @property {Array<{name:string,params:any,trigger:string}>} [cinematicPrimitives]
 * @property {Object} [intent]
 * @property {Object} [scenePosition]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Plane dimensions – derived from atlas rect 512×320 (aspect 1.6)
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 0,
    // map will be set asynchronously
  });

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Load texture synchronously via promise (no await)
  if (config?.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;

      // Simple entrance animation (fade‑in)
      const tl = gsap.timeline();
      tl.to(material, { opacity: 1, duration: 0.5, ease: "power2.out" });
      root.userData._timeline = tl;
    });
  } else {
    // No texture – just make it visible
    material.opacity = 1;
  }

  // Empty handlers placeholder
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (root.userData._timeline) {
      root.userData._timeline.kill();
    }
  };

  return root;
}
